// Reproduces every row of Joseph's data/operating_scenarios.csv (electrical
// package, revised 8 Nov 2026 from Joseph's room-by-room list; regenerated by
// calculations/build_data.py, independent of this code) from src/data/power.ts. Every column is compared:
// total watts, L1, L2, worst leg, % of limit, feeder drop, volts at panel, status.
// Run with: npm test
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { BASE, EMERG, MEGACHEFS, allCircuits, HEATER_OPTIONS, type HeaterOption } from '../data/power'
import { CEILING_A } from '../data/power'
import { feederDropV, generatorStatus, legs, ownedGeneratorShare, utilityStatus, compute, peakState, warnings } from './power'
import { LINKED, SCENARIOS, scenarioIds } from '../data/power'

const csvPath = join(__dirname, '..', 'data', 'electrical', 'operating_scenarios.csv')

function parseLine(l: string): string[] {
  const out: string[] = []
  let cur = ''
  let q = false
  for (const ch of l) {
    if (ch === '"') q = !q
    else if (ch === ',' && !q) {
      out.push(cur)
      cur = ''
    } else cur += ch
  }
  out.push(cur)
  return out
}

const rows = readFileSync(csvPath, 'utf8')
  .replace(/^﻿/, '')
  .trim()
  .split(/\r?\n/)
  .slice(1)
  .map(parseLine)

/** Breakers on for a CSV row, built the same way as the package's build_data.py. */
function idsFor(opt: HeaterOption, source: string, name: string): string[] | null {
  const heatAll = HEATER_OPTIONS[opt].elements.map((e) => e.id)
  const heatOne = ['c12']
  if (source === 'Utility') {
    const map: Record<string, string[]> = {
      'Baseline (continuous loads)': BASE,
      'Baseline + heater, full': [...BASE, ...heatAll],
      'Baseline + heater, staged hold (element 2 off)': [...BASE, ...heatOne],
      'Baseline + 4 MegaChefs': [...BASE, ...MEGACHEFS],
      'Baseline + All American 75X': [...BASE, 'x75'],
      'Baseline + Thor bagger & pump': [...BASE, 'bag'],
      'Baseline + 75X, ZVS & sealer (lab bench)': [...BASE, 'x75', 'zvs', 'seal'],
      'RULE BROKEN: heater full + 4 MegaChefs': [...BASE, ...heatAll, ...MEGACHEFS],
      'THEORETICAL: everything on at once': allCircuits(opt).map((c) => c.id),
    }
    return map[name] ?? null
  }
  const map: Record<string, string[]> = {
    'Emergency baseline': EMERG,
    'Emergency + 36k mini-split #1': [...EMERG, 'c34'],
    'Emergency + 36k + 12k': [...EMERG, 'c34', 'c78'],
    'Emergency + heater (1 element)': [...EMERG, ...heatOne],
    'Emergency + 6,500 W heater': [...EMERG, ...heatOne],
    'Emergency + BOTH heater elements': [...EMERG, ...heatAll],
    'Emergency + Thor bagger & pump': [...EMERG, 'bag'],
    'Emergency + heater + 36k': [...EMERG, ...heatOne, 'c34'],
  }
  return map[name] ?? null
}

// Python's round(x, 1): rounds the exact stored value (71.85 is stored as 71.8499... so gives 71.8),
// and an exact tie such as 83.25 goes to the even digit (83.2). toFixed matches except on exact ties.
const r1 = (n: number) => {
  const exact = Math.abs(n).toFixed(30)
  const [, frac] = exact.split('.')
  if (/^\d50*$/.test(frac)) {
    const down = Math.trunc(Math.abs(n) * 10) / 10
    const lastEven = Math.round(down * 10) % 2 === 0
    const v = lastEven ? down : down + 0.1
    return String(Number((Math.sign(n) * v).toFixed(1)))
  }
  return String(Number(n.toFixed(1)))
}
// Python's f"{x:.0f}" also rounds an exact tie to even (92.5 -> 92).
const pct0 = (n: number) => {
  const [, frac = ''] = Math.abs(n).toFixed(30).split('.')
  if (/^50*$/.test(frac)) {
    const down = Math.trunc(n)
    return `${down % 2 === 0 ? down : down + Math.sign(n)}%`
  }
  return `${n.toFixed(0)}%`
}

describe('operating_scenarios.csv', () => {
  it('has 30 rows', () => {
    expect(rows.length).toBe(30)
  })

  const diffs: string[] = []
  for (const r of rows) {
    const [opt, source, name, totalW, l1A, l2A, worstA, pctLimit, dropPct, volts, status] = r
    it(`${opt} | ${source} | ${name}`, () => {
      const ids = idsFor(opt as HeaterOption, source, name)
      expect(ids, 'scenario is mapped').not.toBeNull()
      const { l1, l2, watts } = legs(new Set(ids!), opt as HeaterOption)
      const worst = Math.max(l1, l2)
      const got: string[] = [String(Math.round(watts)), r1(l1), r1(l2), r1(worst)]
      const want: string[] = [totalW, l1A, l2A, worstA]
      if (source === 'Utility') {
        const vd = feederDropV(worst)
        got.push(pct0((worst / CEILING_A) * 100), `${((vd / 240) * 100).toFixed(2)}%`, (240 - vd).toFixed(1), utilityStatus(worst).status)
        want.push(pctLimit, dropPct, volts, status)
      } else {
        const g = ownedGeneratorShare(watts)
        got.push(`${pct0(g.propane)} LP / ${pct0(g.gasoline)} gas`, '', '', generatorStatus(g.propane).status)
        want.push(pctLimit, dropPct, volts, status)
      }
      // Python prints 234.9 as "234.9" and 233.0 as "233.0"; compare as numbers where numeric.
      const norm = (s: string) => (s !== '' && /^-?\d+(\.\d+)?$/.test(s) ? String(Number(s)) : s)
      if (got.map(norm).join('|') !== want.map(norm).join('|')) diffs.push(`${opt} ${source} ${name}: got ${got.join(', ')} want ${want.join(', ')}`)
      expect(got.map(norm)).toEqual(want.map(norm))
    })
  }

  it('0 differences in total', () => {
    expect(diffs).toEqual([])
  })
})

describe('on-screen scenario presets', () => {
  it('match the CSV scenarios they stand for', () => {
    const check = (key: string, opt: HeaterOption, worst: number) => {
      const s = SCENARIOS.find((x) => x.key === key)!
      const r = compute(new Set(scenarioIds(s, opt)), { heater: opt, source: s.source, fuel: 'propane', genW: 11400, overrides: {} })
      expect(r1(r.worst)).toBe(String(worst))
    }
    check('base', '2x4500', 63.9)
    check('heatfull', '2x4500', 101.4)
    check('heatfull', '6500', 91)
    check('heatstage', '2x4500', 82.6)
    check('mega', '2x4500', 93)
    check('bag', '2x4500', 63.9)
    check('labbench', '2x4500', 75.8)
    check('bad', '2x4500', 130.5)
    check('all', '2x4500', 163.2)
    check('all', '6500', 152.8)
    check('gmax', '6500', 67.4)
  })

  it('every circuit watt total matches the 8 Nov 2026 spec-sheet figures', () => {
    // Hand-worked per box slot (8 Nov 2026): 2 = 7 x 36; 3 = 2 x 208; 7 = 2 x 180 + 255 + 3.3 + 3.3 meters + 2 Inkbird + 380 TAC; 9 = 600 + 600
    // bagger and pump, plus the 208 W wall FFU; 11 = 4 x 60; 12 = 2 x 198 + 3.4; 13 = 16 x 25; 15 = 28.
    const want: Record<string, number> = { s5: 252, s4: 416, s6: 150, stir: 100, zvs: 280, seal: 800, s1: 1003.6, lab4: 28, bag: 1200, ffuw: 208, s9: 240, s2: 399.4, s7: 400, x75: 1650, incs4: 28, f1: 800, f2: 800, m1: 1600, c34: 3600, c78: 1000 }
    for (const c of allCircuits('2x4500')) {
      if (want[c.id] !== undefined) expect(Math.round(c.items.reduce((n, i) => n + i.w, 0) * 1000) / 1000).toBe(want[c.id])
    }
  })
})

describe('8 Nov 2026 room list', () => {
  const ROOMS_WANT: Record<string, string[]> = {
    incubation: ['lennox12a', 'lennox12b', 'led-inc', 'floorfan', 's4-inc', 'co2-inc'],
    packing: ['lennox36a', 'lennox36b', 'thor', 'pump', 'led-pack', 's10', 'co2-pack'],
    fruiting: ['s8', 'inkbird', 't5', 'tac', 'hurricane', 'co2-fruit'],
    lab: ['ffu', 'ffu-wall', 'aa75x', 'stir', 'zvs', 'sealer', 's4-lab', 'chest', 'led-lab'],
    outside: ['fogel1', 'fogel2'],
    boiling: ['mega1', 'mega2', 'mega3', 'mega4', 'heat-c12', 'heat-c12b'],
  }
  const items = allCircuits('2x4500').flatMap((c) => c.items)
  it('puts every piece of equipment in the room Joseph listed, and nothing else', () => {
    for (const [room, ids] of Object.entries(ROOMS_WANT)) {
      expect(items.filter((i) => i.room === room).map((i) => i.id).sort()).toEqual([...ids].sort())
    }
  })
  it('has the quantities Joseph listed', () => {
    const q = (id: string) => items.find((i) => i.id === id)!.qty
    expect(q('led-inc') + q('led-pack') + q('led-lab')).toBe(7)
    expect([q('floorfan'), q('t5'), q('s8'), q('hurricane'), q('ffu') + q('ffu-wall'), q('stir')]).toEqual([4, 16, 2, 2, 3, 4])
  })
  it('drops the BactiZapper (replaced by the ZVS induction sterilizer)', () => {
    expect(items.some((i) => i.id === 'bactizap')).toBe(false)
  })
  it('puts both 36k units on 40 A breakers with #8 wire', () => {
    for (const id of ['c34', 'c56']) {
      const c = allCircuits('2x4500').find((x) => x.id === id)!
      expect([c.breaker, c.wire]).toEqual(['40 A 2-POLE', '#8 CU'])
    }
  })
  it('keeps the pump with the bagger and both Fogels on the generator list', () => {
    expect(LINKED).toEqual({})
    expect(allCircuits('2x4500').find((c) => c.id === 'bag')!.items.map((i) => i.id)).toEqual(['thor', 'pump'])
    expect(EMERG).toEqual(expect.arrayContaining(['f1', 'f2', 's4', 'ffuw'])) // lab HEPA on the generator (Joseph, 6 Nov 2026)
  })
})

describe('breaker box as wired (Joseph, 8 Nov 2026)', () => {
  const cs = allCircuits('2x4500')
  const items = cs.flatMap((c) => c.items)
  const slot = (tag: string) => cs.filter((c) => c.tag === tag).map((c) => c.id)
  // Standard split-phase panel: row = ceil(slot / 2); odd rows on L1, even rows on L2.
  const legOf = (n: number) => (Math.ceil(n / 2) % 2 === 1 ? 'L1' : 'L2')
  it('every 120 V slot sits on the leg its position gives', () => {
    for (const c of cs.filter((x) => /^\d+$/.test(x.tag))) expect(c.leg, c.tag).toBe(legOf(Number(c.tag)))
  })
  it('every 2-pole load spans one L1 slot and one L2 slot', () => {
    for (const c of cs.filter((x) => x.leg === 'B')) {
      const [a, b] = c.tag.split('-').map(Number)
      expect(new Set([legOf(a), legOf(b)])).toEqual(new Set(['L1', 'L2']))
    }
  })
  it('puts the climate line on breaker 7 (Joseph, 8 Nov 2026)', () => {
    expect(cs.find((c) => c.id === 's1')!.items.map((i) => i.id).sort()).toEqual(['co2-inc', 'co2-pack', 'inkbird', 's10', 's8', 'tac'])
    expect(cs.some((c) => c.tag === 'TAC?')).toBe(false)
  })
  it('matches the slot list', () => {
    expect([slot('1'), slot('5'), slot('9'), slot('10'), slot('14'), slot('16'), slot('17'), slot('18'), slot('19'), slot('20')]).toEqual([
      ['m1'], ['stir', 'zvs'], ['bag', 'ffuw'], ['m2'], ['x75'], ['f1'], ['m3'], ['f2'], ['m4'], ['o1'],
    ])
    expect([slot('21-23'), slot('22-24'), slot('25-27'), slot('26-28'), slot('29-31'), slot('30-32')]).toEqual([['c78'], ['c910'], ['c34'], ['c56'], ['c12'], ['c12b']])
  })
  it('shows the MegaChef imbalance: three on L1, one on L2', () => {
    const legs = ['m1', 'm2', 'm3', 'm4'].map((id) => cs.find((c) => c.id === id)!.leg)
    expect(legs).toEqual(['L1', 'L1', 'L1', 'L2'])
  })
  it('flags uneven legs on a MegaChef batch but not on the baseline', () => {
    const cfgU = { heater: '2x4500' as const, source: 'utility' as const, fuel: 'propane' as const, genW: 11400, overrides: {} }
    const ids = (key: string) => new Set(scenarioIds(SCENARIOS.find((s) => s.key === key)!, '2x4500'))
    const run = (on: Set<string>) => warnings(on, cfgU, compute(on, cfgU), peakState(new Date('2026-11-05T21:00:00Z'))).map((w) => w.id)
    expect(run(ids('base'))).not.toContain('imbalance')
    expect(run(ids('mega'))).toContain('imbalance')
  })
  it('flags a generator leg over half the generator even when the total fits', () => {
    const cfgG = { heater: '2x4500' as const, source: 'generator' as const, fuel: 'propane' as const, genW: 11400, overrides: {} }
    const on = new Set([...EMERG, 'c34', 'c78', 's7', 's5', 's4', 'm4'])
    const r = compute(on, cfgG)
    expect(r.watts).toBeLessThan(11400)
    expect(Math.max(r.l1, r.l2)).toBeGreaterThan(47.5)
    expect(warnings(on, cfgG, r, peakState(new Date('2026-11-05T21:00:00Z'))).map((w) => w.id)).toContain('genleg')
  })
  it('keeps nothing marked as a room guess', () => {
    expect(items.filter((i) => i.roomGuess)).toEqual([])
  })
})

describe('operating rules', () => {
  const cfg = (source: 'utility' | 'generator', heater: HeaterOption = '2x4500') => ({ heater, source, fuel: 'propane' as const, genW: 11400, overrides: {} })
  const offPeak = peakState(new Date('2026-11-05T21:00:00Z')) // 15:00 in Costa Rica
  const inPeak = peakState(new Date('2026-11-05T17:00:00Z')) // 11:00 in Costa Rica
  const ids = (key: string, opt: HeaterOption = '2x4500') => new Set(scenarioIds(SCENARIOS.find((s) => s.key === key)!, opt))
  const run = (on: Set<string>, c: ReturnType<typeof cfg>, p = offPeak) => warnings(on, c, compute(on, c), p).map((w) => w.id)

  it('reads Costa Rica time for the ICE peak windows', () => {
    expect(offPeak.inPeak).toBe(false)
    expect(inPeak.inPeak).toBe(true)
    expect(inPeak.window).toEqual({ from: '10:00', to: '12:30' })
  })
  it('baseline breaks no rule', () => {
    expect(run(ids('base'), cfg('utility'))).toEqual([])
  })
  it('heater + MegaChefs trips the heat lockout', () => {
    expect(run(ids('bad'), cfg('utility'))).toContain('heatlock')
  })
  it('heater during an ICE peak window is flagged', () => {
    expect(run(ids('heatfull'), cfg('utility'), inPeak)).toContain('peak')
    expect(run(ids('heatfull'), cfg('utility'), offPeak)).not.toContain('peak')
  })
  it('generator: heater + AC and overload are flagged', () => {
    const w = run(ids('gmax', '6500'), cfg('generator', '6500'))
    expect(w).toContain('genheatac')
    expect(w).toContain('genover')
    expect(run(ids('gboilall'), cfg('generator'))).toContain('genboth')
  })
  it('estimated wattage overrides change the load', () => {
    const on = ids('base')
    // Both 36k units at their 24 A peak (5,760 W) instead of 3,600 W: +18 A per leg .
    const base = compute(on, cfg('utility'))
    const r = compute(on, { ...cfg('utility'), overrides: { lennox36a: 5760, lennox36b: 5760 } })
    expect(r.l1 - base.l1).toBeGreaterThan(17.9)
    expect(r.l1 - base.l1).toBeLessThan(18.1)
  })
})
